    if(internal)n.refreshLatency();else if(s!=null)NetworkRegion.refreshLatency(s,null);
    JSONObject q=internal?n.quality.stats(n.currentEntry,now):NetworkRegion.latency(n.context,s),health=internal?n.quality.currentSample(n.currentEntry,now,n.probeRouteKey()):new JSONObject();String route=internal?"":s==null?"":NetworkRegion.latencyRoute(s);JSONObject displayed=n.latencyReading;boolean displaySample=internal&&n.currentEntry.equals(displayed.optString("entry"))&&n.token.equals(displayed.optString("generation"))&&n.routeSerial==displayed.optLong("routeSerial")&&displayed.optLong("at")>0;
    return J.obj("environmentId",s==null?"":s.environmentId,"generation",s==null?-1:s.environmentGeneration,"runningConfiguration",running,"appliedRevision",s==null?0:s.identityAuditAppliedRevision(),"admission",internal?n.connectionAdmission().name():"","healthStatus",internal?n.healthStatus:"","healthTargetCode",internal?n.healthTargetCode:0,"healthObservedAt",internal?n.healthObservedAt:0,"at",now,"pid",android.os.Process.myPid(),"mode",mode,"configured",prefs.getBoolean("networkConfigured",false),"proxy",!prefs.getString("proxy","").isEmpty(),"connected",s==null?internal&&n.ready&&n.coreAlive():s.networkReady&&!s.offline&&s.guard.allowed()&&s.appliedIdentity.equals(s.networkIdentity())&&(!internal||n.connectionAdmission().usable()),"offline",s!=null&&s.offline,"starting",n.starting||s!=null&&s.connecting,"blocked",internal&&n.recoveryBlocked,"issue",s==null?internal&&n.recoveryBlocked?n.message:"":s.networkIssue,"exitId",internal?n.fingerprint:"","subscriptionId",internal?NativeNetwork.hash(config.optString("subscriptionUrl")):"","ip",internal?n.exitIp:NetworkRegion.exitIp(n.context,s),"observedIp",internal?n.observedExitIp:"","verifiedAt",internal?n.lastVerified:0,"entry",internal?n.currentEntry:"","delay",displaySample?displayed.optInt("delay",-1):internal?health.optInt("delay",-1):q.optInt("delay",-1),"delayAt",displaySample?displayed.optLong("at"):internal?health.optLong("at"):q.optLong("at"),"delayEntry",internal?n.currentEntry:"","latencyMeasuring",internal?n.latencyRefreshQueued||n.measuringLatency:NetworkRegion.latencyRunning,"latencyRemaining",internal?n.latencyRemaining(now):NetworkRegion.latencyRemaining(s,now),"delayHealth",internal&&!displaySample,"healthDelay",internal?health.optInt("delay",-1):-1,"healthDelayAt",internal?health.optLong("at"):0,"delayKind",internal?displaySample?displayed.optString("kind","unknown"):health.optString("kind","unknown"):"response","delayProbe",internal?displaySample?displayed.optJSONObject("probe"):health.optJSONObject("probe"):new JSONObject(),"delayMeasurement",internal?displaySample?displayed.optLong("measurement"):health.optLong("measurement"):0,"route",route,"delayRoute",internal?"":q.optString("route"),"website",internal?n.websiteResult:new JSONObject(),"dnsNext",internal?n.dns.primary(now):"","dnsActive",internal?n.activeDns:"");
